export function getSubjectQuizQuestions(subjectId: string, difficulty: QuizDifficulty = "easy", limit = 10, examMode?: "SSC" | "HSC" | "Admission" | "University"): QuizQuestionWithTopic[] {
  const questions = QUIZ_BY_SUBJECT[subjectId] || [];
  const byDifficulty = questions.filter((q) => q.difficulty === difficulty);
  const byMode = examMode ? byDifficulty.filter((q) => !q.examModes || q.examModes.includes(examMode)) : byDifficulty;
  const pool = byMode.length >= limit ? byMode : byDifficulty;
  return [...pool].sort(() => Math.random() - 0.5).slice(0, limit);
}

export function getQuizCount(subjectId: string, difficulty?: QuizDifficulty): number {
  const questions = QUIZ_BY_SUBJECT[subjectId] || [];
  return difficulty ? questions.filter((q) => q.difficulty === difficulty).length : questions.length;
}
